# React Error Boundary Component

## Implementation

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from 'react';

// ─── Types ────────────────────────────────────────────────────────────────────

interface ErrorDetails {
  error: Error;
  errorInfo: ErrorInfo;
  timestamp: Date;
  componentStack: string;
}

interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: (props: FallbackProps) => ReactNode;
  onError?: (details: ErrorDetails) => void;
  onReset?: () => void;
  resetKeys?: unknown[];
  isolate?: boolean;
}

interface ErrorBoundaryState {
  hasError: boolean;
  errorDetails: ErrorDetails | null;
  retryCount: number;
}

interface FallbackProps {
  error: Error;
  errorDetails: ErrorDetails;
  retryCount: number;
  resetError: () => void;
}

// ─── Logger ───────────────────────────────────────────────────────────────────

const logError = (details: ErrorDetails): void => {
  const { error, errorInfo, timestamp, componentStack } = details;

  console.group(
    `%c⚠ React Error Boundary — ${timestamp.toISOString()}`,
    'color: #ff4d4f; font-weight: bold; font-size: 14px;'
  );
  console.error('Error:', error.message);
  console.error('Stack Trace:', error.stack);
  console.error('Component Stack:', componentStack);
  console.error('Full ErrorInfo:', errorInfo);
  console.groupEnd();

  // Extend here: send to Sentry, Datadog, etc.
  // Sentry.captureException(error, { extra: { componentStack } });
};

// ─── Default Fallback UI ──────────────────────────────────────────────────────

const DefaultFallback: React.FC<FallbackProps> = ({
  error,
  retryCount,
  resetError,
}) => (
  <div role="alert" style={styles.container}>
    <div style={styles.card}>
      <div style={styles.iconWrapper}>
        <span style={styles.icon}>⚠</span>
      </div>

      <h2 style={styles.title}>Something went wrong</h2>

      <p style={styles.message}>
        An unexpected error occurred. You can try again or refresh the page.
      </p>

      <details style={styles.details}>
        <summary style={styles.summary}>Error details</summary>
        <pre style={styles.pre}>{error.message}</pre>
        {error.stack && (
          <pre style={{ ...styles.pre, marginTop: 8, fontSize: 11 }}>
            {error.stack}
          </pre>
        )}
      </details>

      <div style={styles.actions}>
        <button onClick={resetError} style={styles.retryButton}>
          ↺ Try Again {retryCount > 0 && `(${retryCount})`}
        </button>
        <button onClick={() => window.location.reload()} style={styles.reloadButton}>
          ⟳ Reload Page
        </button>
      </div>

      {retryCount >= 3 && (
        <p style={styles.hint}>
          Still failing? Try refreshing the page or contact support.
        </p>
      )}
    </div>
  </div>
);

// ─── Error Boundary Class ─────────────────────────────────────────────────────

class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  static defaultProps: Partial<ErrorBoundaryProps> = {
    resetKeys: [],
    isolate: false,
  };

  state: ErrorBoundaryState = {
    hasError: false,
    errorDetails: null,
    retryCount: 0,
  };

  // Capture error and update state to trigger fallback render
  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return { hasError: true };
  }

  // Log error details after render
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    const details: ErrorDetails = {
      error,
      errorInfo,
      timestamp: new Date(),
      componentStack: errorInfo.componentStack ?? '',
    };

    logError(details);
    this.props.onError?.(details);

    this.setState({ errorDetails: details });
  }

  // Reset when resetKeys change (similar to react-error-boundary)
  componentDidUpdate(prevProps: ErrorBoundaryProps): void {
    const { resetKeys } = this.props;
    const { hasError } = this.state;

    if (
      hasError &&
      resetKeys?.length &&
      resetKeys.some((key, i) => key !== prevProps.resetKeys?.[i])
    ) {
      this.resetError();
    }
  }

  resetError = (): void => {
    this.props.onReset?.();
    this.setState((prev) => ({
      hasError: false,
      errorDetails: null,
      retryCount: prev.retryCount + 1,
    }));
  };

  render(): ReactNode {
    const { hasError, errorDetails, retryCount } = this.state;
    const { children, fallback, isolate } = this.props;

    if (hasError && errorDetails) {
      const fallbackProps: FallbackProps = {
        error: errorDetails.error,
        errorDetails,
        retryCount,
        resetError: this.resetError,
      };

      if (fallback) {
        return fallback(fallbackProps);
      }

      // Isolate mode: wrap in a contained div to prevent layout shifts
      const fallbackUI = <DefaultFallback {...fallbackProps} />;
      return isolate ? <div style={styles.isolate}>{fallbackUI}</div> : fallbackUI;
    }

    return children;
  }
}

// ─── Styles ───────────────────────────────────────────────────────────────────

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '100vh',
    padding: '24px',
    backgroundColor: '#f5f5f5',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
  },
  card: {
    background: '#fff',
    borderRadius: '12px',
    boxShadow: '0 4px 24px rgba(0,0,0,0.1)',
    padding: '40px',
    maxWidth: '520px',
    width: '100%',
    textAlign: 'center',
  },
  iconWrapper: {
    marginBottom: '16px',
  },
  icon: {
    fontSize: '48px',
    lineHeight: 1,
  },
  title: {
    margin: '0 0 12px',
    fontSize: '22px',
    fontWeight: 700,
    color: '#1a1a1a',
  },
  message: {
    margin: '0 0 24px',
    fontSize: '15px',
    color: '#555',
    lineHeight: 1.6,
  },
  details: {
    textAlign: 'left',
    marginBottom: '24px',
    background: '#fafafa',
    border: '1px solid #e8e8e8',
    borderRadius: '8px',
    padding: '12px 16px',
  },
  summary: {
    cursor: 'pointer',
    fontSize: '13px',
    fontWeight: 600,
    color: '#888',
    userSelect: 'none',
  },
  pre: {
    margin: '8px 0 0',
    fontSize: '12px',
    color: '#ff4d4f',
    whiteSpace: 'pre-wrap',
    wordBreak: 'break-word',
    overflowX: 'auto',
  },
  actions: {
    display: 'flex',
    gap: '12px',
    justifyContent: 'center',
    flexWrap: 'wrap',
  },
  retryButton: {
    padding: '10px 24px',
    fontSize: '14px',
    fontWeight: 600,
    color: '#fff',
    background: '#1677ff',
    border: 'none',
    borderRadius: '8px',
    cursor: 'pointer',
    transition: 'background 0.2s',
  },
  reloadButton: {
    padding: '10px 24px',
    fontSize: '14px',
    fontWeight: 600,
    color: '#555',
    background: '#f0f0f0',
    border: 'none',
    borderRadius: '8px',
    cursor: 'pointer',
    transition: 'background 0.2s',
  },
  hint: {
    marginTop: '16px',
    fontSize: '13px',
    color: '#ff4d4f',
  },
  isolate: {
    position: 'relative',
    minHeight: '200px',
  },
};

export default ErrorBoundary;
export type { ErrorBoundaryProps, FallbackProps, ErrorDetails };
```

## Usage Examples

```tsx
// App.tsx — Basic usage
import ErrorBoundary from './ErrorBoundary';

// 1. Wrap your entire app
export default function App() {
  return (
    <ErrorBoundary>
      <Router>
        <Routes />
      </Router>
    </ErrorBoundary>
  );
}

// ─────────────────────────────────────────────────────────────────────────────

// 2. Custom fallback UI
function Dashboard() {
  return (
    <ErrorBoundary
      fallback={({ error, resetError, retryCount }) => (
        <div className="error-panel">
          <h3>Dashboard failed to load</h3>
          <code>{error.message}</code>
          <button onClick={resetError}>Retry ({retryCount})</button>
        </div>
      )}
    >
      <DashboardContent />
    </ErrorBoundary>
  );
}

// ─────────────────────────────────────────────────────────────────────────────

// 3. Reset on route change (resetKeys)
function RouteWrapper() {
  const { pathname } = useLocation();

  return (
    <ErrorBoundary
      resetKeys={[pathname]}
      onReset={() => console.log('Error boundary reset')}
    >
      <Outlet />
    </ErrorBoundary>
  );
}

// ─────────────────────────────────────────────────────────────────────────────

// 4. Isolated widget (won't break surrounding layout)
function Sidebar() {
  return (
    <aside>
      <ErrorBoundary isolate onError={(details) => reportToAnalytics(details)}>
        <RecommendationsWidget />
      </ErrorBoundary>
    </aside>
  );
}

// ─────────────────────────────────────────────────────────────────────────────

// 5. External error reporting (e.g. Sentry)
function AppWithMonitoring() {
  const handleError = (details: ErrorDetails) => {
    Sentry.captureException(details.error, {
      extra: {
        componentStack: details.componentStack,
        timestamp: details.timestamp,
      },
    });
  };

  return (
    <ErrorBoundary onError={handleError}>
      <App />
    </ErrorBoundary>
  );
}
```

## Testing the Boundary

```tsx
// BuggyComponent.tsx — for testing
import { useState } from 'react';

export function BuggyComponent() {
  const [shouldThrow, setShouldThrow] = useState(false);

  if (shouldThrow) {
    throw new Error('💥 Test error from BuggyComponent');
  }

  return (
    <button onClick={() => setShouldThrow(true)}>
      Trigger Error
    </button>
  );
}

// In your test file
import { render, screen, fireEvent } from '@testing-library/react';
import ErrorBoundary from './ErrorBoundary';
import { BuggyComponent } from './BuggyComponent';

// Suppress console.error noise in tests
beforeEach(() => jest.spyOn(console, 'error').mockImplementation(() => {}));
afterEach(() => jest.restoreAllMocks());

test('renders fallback UI on error', () => {
  const ThrowOnRender = () => { throw new Error('Test error'); };

  render(
    <ErrorBoundary>
      <ThrowOnRender />
    </ErrorBoundary>
  );

  expect(screen.getByRole('alert')).toBeInTheDocument();
  expect(screen.getByText(/something went wrong/i)).toBeInTheDocument();
});

test('resets error state on retry', () => {
  let shouldThrow = true;
  const MaybeThrow = () => {
    if (shouldThrow) throw new Error('Oops');
    return <div>Recovered!</div>;
  };

  render(<ErrorBoundary><MaybeThrow /></ErrorBoundary>);
  expect(screen.getByRole('alert')).toBeInTheDocument();

  shouldThrow = false;
  fireEvent.click(screen.getByText(/try again/i));

  expect(screen.getByText('Recovered!')).toBeInTheDocument();
});
```

## Key Design Decisions

| Feature | Approach |
|---|---|
| **Error capture** | `getDerivedStateFromError` + `componentDidCatch` |
| **Logging** | Grouped `console.error` with timestamp; extensible for Sentry/Datadog |
| **Retry** | Increments `retryCount`, resets state to re-render children |
| **Auto-reset** | `resetKeys` prop triggers reset when values change (e.g., route change) |
| **Custom UI** | Render prop `fallback` for full control over fallback appearance |
| **Isolation** | `isolate` prop wraps fallback to prevent layout disruption |
| **TypeScript** | Fully typed props, state, and exported interfaces |
